# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

# A token minted for a delegated read can carry a raised role (an admin whose
# older role is employee). It must never authorize a write, so the stored entry
# stays exactly as it was, however many times the request is sent.
RSpec.describe "Timekeeping entry writes refuse read-purpose tokens on PATCH" do
  around do |example|
    with_timekeeping_env(Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem) { example.run }
  end

  it "refuses a read-purpose admin token on PATCH, leaves the colleague's entry unchanged, and a replay changes nothing either" do
    colleague_entry = Entry.create!(
      company_id: 1, user_id: 8, project_id: 10, work_date: Date.new(2026, 1, 5),
      duration: 60.0, note: "work", bill_status: "unbilled"
    )
    before_change = colleague_entry.reload.attributes
    read_token = mint_token({ sub: 7, company_id: 1, role: "admin", purpose: "read" })
    headers = {
      "Authorization" => "Bearer #{read_token}", "Content-Type" => "application/json",
      "Idempotency-Key" => SecureRandom.uuid, "Ownership-Generation" => "1", "If-Match" => colleague_entry.version.to_s
    }
    body = { note: "changed through a read token", duration: 120.0 }.to_json

    2.times do
      patch "/v1/companies/1/entries/#{colleague_entry.id}", params: body, headers: headers

      expect(response.status).to eq(403)
      expect(response.parsed_body).to eq({ "reason" => "forbidden" })
    end

    expect(colleague_entry.reload.attributes).to eq(before_change)
  end
end

RSpec.describe "Timekeeping entry writes refuse read-purpose tokens on POST" do
  around do |example|
    with_timekeeping_env(Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem) { example.run }
  end

  it "refuses a read-purpose admin token on POST and stores no entry, even when the same request is sent again" do
    read_token = mint_token({ sub: 7, company_id: 1, role: "admin", purpose: "read" })
    headers = {
      "Authorization" => "Bearer #{read_token}", "Content-Type" => "application/json",
      "Idempotency-Key" => SecureRandom.uuid, "Ownership-Generation" => "1"
    }
    body = {
      user_id: 8, project_id: 10, work_date: "2026-01-05", duration: 60.0, note: "for a colleague",
      source: "manual", source_metadata: {}
    }.to_json

    expect do
      2.times do
        post "/v1/companies/1/entries", params: body, headers: headers

        expect(response.status).to eq(403)
        expect(response.parsed_body).to eq({ "reason" => "forbidden" })
      end
    end.not_to change(Entry, :count)
  end
end
